import React from 'react';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { useMeterBarLayoutSize } from '../../shared/context/MeterBarLayoutSize.context.js';
import { getChartElementsSizes } from '../../shared/functions/get-chart-elements-sizes.js';
import { DEFAULT_GAP_WIDTH } from '../../shared/types/default.js';

interface MeterBarIndicatorProps {
  position: number;
}

const INDICATOR_GAP = 8;
const INDICATOR_WIDTH = 2;
const INDICATOR_START_Y = -4;

export const MeterBarThresholdIndicator = ({
  position,
}: MeterBarIndicatorProps) => {
  const { size } = useMeterBarLayoutSize();
  const { chartHeight } = getChartElementsSizes(size);

  return (
    <rect
      x={position - DEFAULT_GAP_WIDTH}
      y={INDICATOR_START_Y}
      width={INDICATOR_WIDTH}
      height={chartHeight + INDICATOR_GAP}
      fill={Colors.Icon.Neutral.Default}
    ></rect>
  );
};
